import json
from z3 import *

# Time definitions (in minutes since midnight)
DAY_START = 9 * 60  # 09:00
DAY_END = 18 * 60 + 5  # 18:05
BUDGET = 83

# Places definition: (id, cost, duration, open_min, open_max, is_must)
places = {
    "supertree_grove": {"cost": 0, "dur": 45, "open": 5*60, "close": 24*60, "must": True},
    "buddha_tooth": {"cost": 0, "dur": 45, "open": 7*60, "close": 17*60, "must": False},
    "east_coast_lagoon": {"cost": 15, "dur": 60, "open": 10*60+30, "close": 22*60+30, "must": True},
    "skyhelix": {"cost": 20, "dur": 30, "open": 10*60, "close": 21*60+30, "must": False},
    "ocbc_skyway": {"cost": 14, "dur": 30, "open": 9*60, "close": 21*60, "must": False},
    "fort_canning": {"cost": 0, "dur": 60, "open": 0, "close": 24*60, "must": False},
}

place_ids = list(places.keys())

# Travel times (row -> column)
travel_matrix = {
    "supertree_grove": {"supertree_grove": 0, "buddha_tooth": 16, "east_coast_lagoon": 30, "skyhelix": 24, "ocbc_skyway": 11, "fort_canning": 16},
    "buddha_tooth": {"supertree_grove": 16, "buddha_tooth": 0, "east_coast_lagoon": 35, "skyhelix": 20, "ocbc_skyway": 16, "fort_canning": 14},
    "east_coast_lagoon": {"supertree_grove": 30, "buddha_tooth": 35, "east_coast_lagoon": 0, "skyhelix": 44, "ocbc_skyway": 30, "fort_canning": 34},
    "skyhelix": {"supertree_grove": 24, "buddha_tooth": 20, "east_coast_lagoon": 44, "skyhelix": 0, "ocbc_skyway": 24, "fort_canning": 23},
    "ocbc_skyway": {"supertree_grove": 11, "buddha_tooth": 16, "east_coast_lagoon": 30, "skyhelix": 24, "skyhelix": 24, "fort_canning": 16},
    "fort_canning": {"supertree_grove": 16, "buddha_tooth": 14, "east_coast_lagoon": 34, "skyhelix": 23, "ocbc_skyway": 16, "fort_canning": 0}
}
# Fix typo in ocbc_skyway key mapping
travel_matrix["ocbc_skyway"]["skyhelix"] = 24

s = Solver()

# Decision variables
visited = {p: Bool(f"visited_{p}") for p in place_ids}
start = {p: Int(f"start_{p}") for p in place_ids}
end = {p: Int(f"end_{p}") for p in place_ids}

# Budget constraint
total_cost = Sum([If(visited[p], places[p]["cost"], 0) for p in place_ids])
s.add(total_cost <= BUDGET)

# Must-visit constraints
for p in place_ids:
    if places[p]["must"]:
        s.add(visited[p])

# Time bounds, durations, and opening hours constraints
for p in place_ids:
    dur = places[p]["dur"]
    op = places[p]["open"]
    cl = places[p]["close"]

    s.add(Implies(visited[p], And(
        start[p] >= DAY_START,
        end[p] <= DAY_END,
        start[p] >= op,
        end[p] <= cl,
        end[p] == start[p] + dur
    )))

# Specific constraint for SkyHelix: no earlier than 10:00 (600) and done by 11:30 (690)
s.add(Implies(visited["skyhelix"], And(
    start["skyhelix"] >= 600,
    end["skyhelix"] <= 690
)))

# Non-overlapping and travel time constraints for all pairs of distinct places
for i, p1 in enumerate(place_ids):
    for j, p2 in enumerate(place_ids):
        if i != j:
            t_travel = travel_matrix[p1][p2]
            # If both are visited, either p1 finishes + travel <= p2.start OR p2 finishes + travel <= p1.start
            s.add(Implies(
                And(visited[p1], visited[p2]),
                Or(
                    end[p1] + t_travel <= start[p2],
                    end[p2] + t_travel <= start[p1]
                )
            ))

if s.check() == sat:
    m = s.model()
    result = []
    for p in place_ids:
        if is_true(m[visited[p]]):
            result.append({
                "location_id": p,
                "start": m[start[p]].as_long(),
                "end": m[end[p]].as_long()
            })
    # Sort by start time for neatness
    result.sort(key=lambda x: x["start"])
    print(json.dumps(result))
else:
    print("UNSAT")
